// Deactivate Test Users
List<User> testUsers = [SELECT Id, IsActive FROM User WHERE Username LIKE '%flowstral.test%' AND IsActive = true];
if(!testUsers.isEmpty()) {
    for(User u : testUsers) {
        u.IsActive = false;
    }
    update testUsers;
    System.debug('Deactivated ' + testUsers.size() + ' test users');
} else {
    System.debug('No active test users to deactivate');
}

// Delete Permission Set Assignments
List<PermissionSet> testPS = [SELECT Id FROM PermissionSet WHERE Name LIKE 'Flowstral_Test%'];
if(!testPS.isEmpty()) {
    List<PermissionSetAssignment> assignments = [SELECT Id FROM PermissionSetAssignment WHERE PermissionSetId IN :testPS];
    if(!assignments.isEmpty()) {
        delete assignments;
        System.debug('Deleted ' + assignments.size() + ' permission set assignments');
    }
}

