// Remove role assignments
List<UserRole> testRoles = [SELECT Id FROM UserRole WHERE DeveloperName LIKE 'Flowstral_Test%'];
if(!testRoles.isEmpty()) {
    List<User> usersWithRoles = [SELECT Id, UserRoleId FROM User WHERE UserRoleId IN :testRoles];
    for(User u : usersWithRoles) {
        u.UserRoleId = null;
    }
    if(!usersWithRoles.isEmpty()) {
        update usersWithRoles;
