// Delete Roles - bottom up (children first)
List<String> roleOrder = new List<String>{
    'Flowstral_Test_Sales_Rep',
    'Flowstral_Test_Sales_Manager',
    'Flowstral_Test_VP_Sales',
    'Flowstral_Test_CEO'
};

for(String roleName : roleOrder) {
    List<UserRole> role = [SELECT Id FROM UserRole WHERE DeveloperName = :roleName];
    if(!role.isEmpty()) {
        try {
            delete role;
            System.debug('Deleted role: ' + roleName);
        } catch(Exception e) {
            System.debug('Could not delete ' + roleName + ': ' + e.getMessage());
        }
    }
}

